  "hands": "single",
  "description": "Abhaya Mudra I is a single-hand gesture (asamyukta hasta) common to the yoga tradition. It is referred to as the “seal of fearlessness” and is used in Hinduism, Indian tantrism, and Buddhism. The mudra is most commonly employed as a gesture of protection and pacification in ritual practice and in iconographic depictions of deities, sages, and saints. It is used to dispel fear and to evoke the direct experience of openness. It also represents the Five Elements resting in their natural relationship, with the center of the palm as the bindu, or central point of focus.",
  "technique": "Raise the right hand in front of your right shoulder, palm facing forward, relaxed, with the fingers extending upward. Keep your shoulder relaxed, elbow bent, and hand still. Feel the center of your palm warm, as if radiating a soft light. Rest the left hand in your lap with the palm up, or let it hang gently at your side during standing or walking practice.",
  "application": "Use Abhaya Mudra I during seated meditation and self-reflection when fear and ego clinging arise. Hold the mudra for 5 to 45 minutes. Imagine that whatever causes you fear is looking directly into the center of your upheld palm. Feel that your courage and openness are unwavering, and fear is subdued by the power of your unswerving acceptance. Through regular practice in this way, fear is subliminated into fearlessness.",
  "benefits": "Calms the mind, reduces anxiety and inner conflict, removes attachment and aversion to thoughts, emotions, and sensations.",
  "note": "",
