  "hands": "joint",
  "description": "Abhaya Hrdaya Mudra is a joint-hand gesture (samyukta hasta) used in the yoga tradition as a powerful energy conductor and mind seal. It is a lesser-known tantric gesture that, according to oral tradition, was traditionally kept secret among initiates. The mudra is known for its unique ability to rejuvenate one’s vital force and reduce fragmented thoughts and scattered energy.",
  "technique": "Raise the hands in front of the chest, palms facing center. Cross the wrists with the backs of the hands touching, right hand closest to your body, palms facing to the sides. Firmly interlock the index, middle, and little fingers, while connecting the tips of the thumb and ring finger on both hands, forming two rings.",
  "application": "In a seated meditation posture, hold the mudra firmly to your chest and pull down gently rooting it into the base of your sternum. Breathe naturally and hold for 5 to 45 minutes.",
  "benefits": "Nourishes the heart and lungs, improves digestion, imparts a powerful sense of vitality and calm, can help reduce nightmares and reestablish basic sanity to a troubled mind. Use of this mudra is especially helpful during times of exhaustion, healing from debilitating illness, or regaining strength after surgery. Energetically, it allows heat to descend from the head through the chest down into the belly, thus regulating the healthy function of all the internal organs.",
  "note": "This mudra may be performed lying down (especially in the case of recuperation after surgery or serious illness), but it is important that the upper body be slightly elevated so that the head and chest are higher than the belly. This takes pressure off the heart and regulates blood pressure.",
