  "hands": "joint",
  "description": "Adhomukha Mudra is a joint-hand gesture (samyukta hasta) used in the yoga tradition for healing, especially cancer. It is part of the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the tenth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "Join the tips of the thumbs together with the palms facing downward. Point all the other fingers down while resting the tops of the fingers and first knuckles together. Keep all fingers straight and relaxed. Hold the mudra at the level of the waist, thumbs just in front of the navel.",
  "application": "In a comfortable meditation posture, hold the mudra for 2 to 5 minutes while focusing on the navel and evoking the sense of warmth and rootedness. For healing, especially serious illness such as cancer, hold the mudra for 20 to 45 minutes, two to three sessions per day is ideal.",
  "benefits": "Activates the digestive fire, increases transformative and self-healing powers, reduces toxicity, readies the mind for meditation, prayer, or recitation of mantras.",
  "note": "For women practicing during their menstrual cycle, move the position of the mudra to the heart center, with the tips of the thumbs lightly touching the base of the sternum.",
