  "hands": "joint",
  "description": "Ajna Chakra Mudra is a joint-hand gesture (samyukta hasta) used in Indian tantric Yoga and Japanese martial arts to open the “third eye.” It employs the relationship of Fire (thumb) and Air (index) Elements to focus attention and intensify energy in an effort to awaken inner vision.",
  "technique": "Extend the left index finger and curl the other fingers into the palm. Use the left thumb to cover the nails of the other three fingers. Grasp the extended index finger with your right hand, using your right thumb to press gently on the outer corner of the nail bed of the left index finger.",
  "application": "In a seated meditation posture, hold the mudra in your lap and focus lightly on the space between your eyebrows. For increased intensity, bring the mudra a few inches in front of your forehead, pointing the tip of the extended index finger toward the third eye center. Hold for 1 to 2 minutes, then lower the mudra back into the lap.",
  "benefits": "Awakens the Ajna Chakra, opens spiritual vision, stimulates the pituitary gland, clarifies the mind, improves concentration and intuition.",
  "note": "",
  "caution": "Do not hold the mudra in front of the eyebrow center for more than 2 minutes. This is a powerful mudra that is best learned under the guidance of a competent teacher. If used inappropriately, it can generate excess heat in the head that can be harmful to the brain, eyes, and nervous system.",
