  "description": "Alapadma Mudra is the twentieth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. It is noted in the Natya Shastra as Ala-pallava. According to mythology, the mudra originates from Shri Krishna, referring to the time when he was a young child stealing butter and milk. The associated sage is Vasanta, race is Gandharva, color is dusky, and deity is Surya, the sun.",
  "technique": "Turn your palm to face upward, stretching the fingers apart. Bring your little finger toward your palm and fan out the rest of the fingers evenly away from the little finger, with the thumb extended 90 degrees to the index finger.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Vikacha-abja (“a fully bloomed lotus”); Kapittha-diphala (“wood apple”); Avarthaka (“circular movement”); Kucha (“breast”); Viraha (“yearning to the beloved”); Mukura (“mirror”); Poorna-chandra (“full moon”); Saundarya-bhavana (“beautiful form”); Dhamilla (“hair-knot”); Chandra-shala (“moon pavilion”); Grama (“village”); Udru-thakopa (“great anger”); Tataka (“pond” or “lake”); Shakata (“cart”); Chakravaka (“type of bird”); Kala-kalarava (“murmuring sound”); Slagana (“praise”). Additional usages are fresh ghee, sweets, head, crown, braided hair, cluster of flowers, ball, dancing, fort, palace, and sweetness.",
