  "hands": "joint",
  "description": "Anjali Mudra is commonly used in yoga and Indian dance. It is the first hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra, Abhinaya Chandrika, and Hasta Lakshana Deepika. The associated patron deity is Ksetrapala.",
  "technique": "Join the hands palm to palm in front of the chest, with the fingers collected and extended upward.",
  "application": "Namaskaram (“to bow or salute”). Used to bow to deities (“Devata”), teachers (“Guru”), and highly regarded people (“Vipranam”). The gesture is held above the head for deities, in front of the face for elders and teachers, and in front of the chest for general respect. It is also used to show obedience, to clap a beat, to indicate the form of Shiva, for meditation, and to await instruction from one’s guru. Anjali Mudra is used extensively as part of the spiritual cultures of East and West as a gesture of prayer, to show respect, humble oneself, and surrender to the greatness of life.",
  "benefits": "Calming and centering, facilitates connection to the heart and central channel (sushumna-nadi), evokes feelings of humility, reverence, and devotion.",
