  "description": "Ardhachandra Mudra is the sixth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra and the Abhinaya Chandrika. According to mythology, this gesture originated from Shiva’s desire for ornaments, of which the moon is one. The associated sage is Atri, race is Vaishya, color is smoky, and patron deity is Mahadeva.",
