  "hands": "single",
  "description": "Ardhapataka Mudra is the third hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. It is also found in Buddhist and Hindu ritual and art depicting or evoking a deity.",
  "technique": "Raise your hand to face outward with your fingers collected and extended upward. Bend your thumb slightly to touch the base of the index finger. Bend the ring and little finger 90 degrees at the middle joint.",
  "application": "Primarily used by performing artists to create context and express emotional states and specific actions. Viniyoga: Pallava (“tender leaf” or “new growth”); Phalaka (“wooden plank” or “panel for drawing”); Theera (“river bank”); Ubayoo-rithi-Vachaka (“two” or “two people together”); Krakacha (“saw”); Churi-kayancha (“pocket knife”); Dvaja (“temple flag”); Gopura-sringayoh (“horns on top of temple tower).",
  "benefits": "",
  "note": "",
  "caution": "",
