  "hands": "joint",
  "description": "Bherunda Mudra is the twenty-third hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "Form Kapittha Mudra with each hand, joining the inner wrists in front of your chest. A variation of this mudra is performed with the wrists across from each other, so the Kapittha hands are back to back.",
  "application": "Used to denote the Bherunda, which is a two-headed mythological bird of Hindu mythology. Bherunda is considered a fierce creature, and is the form that Narasimha (the half-lion incarnation of Vishnu) turned into during his epic battle with the demon.",
