  "description": "Chakra Mudra II is a joint-hand gesture (samyukta hasta) ritual mudra used in the Indian tantric tradition and in Japanese Buddhism (Vajrayana tradition), where it is employed by priests as a gesture of offering.",
  "technique": "Interlace the fingers of both hands. Extend the ring fingers, touching the tips of the two fingers together.",
  "application": "In a comfortable seated position, hold the mudra in front of the navel. Soften the belly and breathe naturally. Feel the belly grow warm, as if the sun is shining inside your abdomen. Hold for 5 to 45 minutes.",
  "benefits": "Centering and grounding, improves digestion, assimilation and elimination, reduces gas and bloating, increases vigor and self-confidence.",
