  "description": "Chandra Mudra is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of the nine planets (Nava-Graha Hastas) as described in the Abhinaya Darpana. It indicates the character of the Moon.",
  "technique": "Assume Alapadma Mudra with your left hand and Pataka Mudra with your right hand. Place your hands by your shoulders and stand in sama position (straight and elongated posture). Keep your gaze natural and directed upward.",
  "application": "To denote the Moon.",
  "benefits": "",
