  "description": "Chandrakala Mudra is the fourteenth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "Bend the little, ring, and middle fingers into the palm. Extend the index finger and thumb, forming a 90-degree angle.",
  "application": "Primarily used in dance and theater to create context and express emotional states or specific actions. Viniyoga: Chandra (“Moon”); Mukha (“face”); Pradesha (“the distance between the tip of the index finger and the thumb”); Shivasya Makuta (“Shiva’s crown”); Ganganadyam (“river Ganges”); Laguda (“axe” or “cane”).",
  "benefits": "Stimulates the lungs, opens the airways, tones the large intestine, relieves constipation.",
