  "description": "Gavaksha Mudra is a joint-hand gesture (samyukta hasta) common to Odissi Dance.",
  "technique": "Form Pataka Mudra with each hand, leaving the fingers slightly separated. Hold the right hand with the palm facing outward, fingers pointing upward at your right side. Place the left hand across the right, palm facing you. The fingers are slightly separated, leaving gaps to peek through.",
  "application": "Used by performing artists to express the shyness of the heroine, as she half hides and half peeks through this hand gesture.",
  "benefits": "",
  "note": "This mudra is very similar to Chakra Mudra. The difference is that there are spaces between the fingers, and the placement of the gesture is in front of the face, slightly off to the side.",
