  "hands": "joint",
  "description": "Granthita Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the fourteenth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "Clasp the hands together with the left index finger on top of the right. Lightly touch the tips of thumbs and index fingers, forming two rings.",
  "application": "In a comfortable seated position, hold the mudra in front of the throat. Relax the tongue, jaw, and shoulders. Soften the belly and breathe naturally. Feel the inside of the mouth and throat as a hollow space filled with clear light. Hold for 5 to 45 minutes.",
  "benefits": "Prepares the mind for meditation, opens Vishuddha Chakra (the throat center), benefits the voice, improves thyroid function, increases the body’s self-healing capacity, especially in cases of cancer.",
  "note": "",
  "caution": "",
