  "english": "“containing the spirit”",
  "altNames": [],
  "bookPage": null,
  "pdfPage": null,
  "traditions": [
   "yoga"
  ],
  "hands": "single",
  "description": "Hamsi Mudra is a single-hand gesture (asamyukta hasta) common to the Hindu and yoga traditions. It is found in the Yoga Tattva Mudra Vijnana form where it is used to relieve obstacles and restore child-like joy and laughter.",
  "technique": "Join the tips of the middle, ring, and little fingers with the tip of the thumb. Extend the index finger.",
  "application": "This mudra may be done in any position; while walking, standing, sitting, or reclining. It is best to approach Hamsi Mudra with the spirit of play and exploration. Hold as long as you like.",
  "benefits": "Removes obstacles in one’s life, eases depression and sadness, evokes feelings of lightness and laughter, benefits the lungs and large intestine, improves assimilation of nutrients and elimination of waste.",
  "note": "In India, Hamsi Mudra is commonly practiced along with the recitation of mantras or prayers. It is commonly used during ritual worship, puja or yajna, to increase the effects of the intended ritual.",
  "caution": "",
  "categories": [
   "Depression",
   "Detox"
  ],
  "chakras": [],
  "function": "Removes obstacles in one’s life, eases depression and sadness",
  "tidbit": "It is found in the Yoga Tattva Mudra Vijnana form where it is used to relieve obstacles and restore child-like joy and laughter.",
