  "description": "Kaleshvara Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It works primarily with the Elements of Fire and Ether, is used to calm the mind, and as a tool to reflect clearly on one’s actions.",
  "technique": "Join the tips of the middle fingers and extend them forward. Fold the index, ring, and little fingers in toward the palms, touching them at the middle joints. Touch the tips of the thumbs together and point them toward the heart.",
  "application": "In a comfortable seated position, hold the mudra in front of the chest. Drop the shoulders and let the elbows find a natural, relaxed position. Turn your attention inward, allowing the mind to gaze upon itself. Without preference or attachment, simply notice what arises. Hold for 5 to 45 minutes.",
  "benefits": "Calms and clears the mind, benefits the brain, strengthens the heart and pericardium, assists in the breaking of negative patterns and addictive behaviors.",
