  "description": "Kamajayi Mudra is a single-hand gesture (asamyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form where it is used to subliminate sexual energy into spiritual aspirations.",
  "technique": "Cover the nail of the thumb with the pad of the index finger. The remaining fingers stay relaxed and slightly curled.",
  "application": "This mudra may be done in any position; while walking, standing, sitting, or reclining. It is also effective when applied during practice of yoga asanas (postures) where the arms are outstretched.",
  "benefits": "Restrains the outflow of excess passion and sexual desire, causes sexual energy to turn inward and upward (thereby assisting the practice of meditation), strengthens digestion, assimilation, and elimination.",
  "note": "Kamajayi Mudra is traditionally used by celibate yogis while on solitary meditation retreat. It may be employed anytime you wish to temper the flames of sexual desire.",
  "caution": "Use of this mudra should never be inspired by feelings of guilt or shame around sex or sexuality. A repressive approach to sexual energy can cause serious physiological and psychological problems. Sexual energy is one of the most beautiful and powerful sources of energy in the human body. A balanced and healthy relationship to sexuality is essential for health, longevity, and spiritual growth.",
