  "technique": "Place your hands about 6 inches in front of your navel, with the palms face up and middle fingers touching at the tips. Keep your shoulders relaxed and arms slightly rounded.",
  "application": "Used at the beginning of a type of ancient South Indian dance called Svabhava Natana (“spontaneous pure dance”). Denotes swing, motionless, “heavy with drink,” lines, and union. This mudra is often used in Classical Indian Dance to initiate a graceful “pure dance” movement.",
