  "hands": "single",
  "description": "Kartarimukha Mudra II is the fourth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. According to mythology, this mudra originated from Shiva when he set out to slay the demon Jatadhara. According to legend, he fixed his middle finger in the center of the earth and drew a circle around the circumference of the earth with his index finger, and this is how Kartarimukha Mudra was created. The associated sage is Parjanya (“rain god”), race is Kshatriya, color is copper, and patron deity is Vishnu.",
  "technique": "Raise your hand with the palm facing forward, fingers pointing upward. Bend the little and ring fingers 90 degrees at the lower joint. Separate the index and middle fingers into a scissor-like shape. Keep the thumb flush against the side of the hand.",
  "application": "See Kartarimukha Mudra I.",
  "benefits": "",
  "note": "Another variation, mentioned in the Odissi Dance Pathfinder, is with fingers and thumb extended upward; bend the middle and ring fingers deep toward the palm.",
