  "hands": "single",
  "description": "Kashyapa Mudra is a single-hand gesture (asamyukta hasta) used in the Hindu tradition to depict the union of linga and yoni, and to symbolize Kashyapa Rishi.",
  "technique": "Place the tip of the thumb in the web between the middle and ring fingers. Close the remaining fingers as if making a fist.",
  "application": "In a comfortable seated position, form the mudra with each hand and place the hands on the thighs, palms facing up. Relax the throat, chest, and belly. Breathe naturally and hold for 5 to 45 minutes.",
  "benefits": "Grounding and centering, balances masculine and feminine qualities, protects against negative energies and unfriendly or confused spirits (sometimes called “orphan spirits”).",
  "note": "Kashyapa Mudra can also be used as a protective seal placed in the small of the lower back during energetic purification of a room or building (a practice similar to what is commonly called “smudging” in Native American traditions). In this case, the mudra is formed with the left hand while the right holds a stick of incense or bundle of dried sage.",
  "caution": "",
