  "hands": "single",
  "description": "Katakamukha Mudra I is the twelfth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. According to mythology, this mudra originated from Guha when he practiced archery in front of Shiva. The associated sage is Bhargava, race is Deva, color is gold, and patron deity is Raghu Rama.",
  "technique": "Join the pad of the thumb to the upper joint creases of the index and middle fingers. Stretch the ring and little fingers upward.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. It is one of the most common mudras used in Pallavis (“pure dance”). Viniyoga: Kusuma-apachaye (“plucking flowers”); Mukta-srak-damnam-dharanam (“wearing a necklace of pearls or flowers”); Nagavalli-pradhanam (“offering betel leaves”); Kasturika-adivastunam-peshana (“preparing paste for musk, etc.”); Gandhavasana (“to smell”); Vachana (“to speak”); Drishti (“glancing”).",
  "benefits": "",
  "note": "",
  "caution": "",
