  "application": "Sara-madhya-akarshanam (“drawing the arrow in the center of the bow”); holding a mirror, fanning, holding reins, breaking a twig, cleaning the teeth, plucking flowers, embracing, holding a disc, pulling a rope, and tucking or holding the loose end of a veil or a robe.",
