  "hands": "joint",
  "description": "Katakavardhana Mudra is the ninth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra. The patron deity associated with it is Yaksharaja.",
  "technique": "Form Katakamukha Mudra I with each hand and cross at the wrists. Keep the gesture a hand’s distance away from your body.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Pattabhisheke (“coronation”); Pujayam (“ritual”); Vivaha-ashishi (“marriage blessings”). Additional usages denote: deliberation, erotic mood, pacification, certainty, and the dances known as Jakkini-natana and Danda-lasya.",
  "benefits": "",
  "note": "",
  "caution": "",
