  "hands": "joint",
  "description": "Ketu Mudra is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of the nine planets (Nava-Graha Hastas) as described in the Abhinaya Darpana. In Vedic astrology, Ketu is the Moon’s south (descending) node. Ketu is generally referred to as a “shadow” planet.",
  "technique": "Assume Suchi Mudra with your left hand and Pataka Mudra with your right hand. Place your hands in front of your chest. Evoke a cruel gaze and mood.",
  "application": "To denote the descending (south) lunar node, Ketu.",
