  "hands": "joint",
  "description": "Kubera Mudra I is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of sixteen Deva Hastas, denoting Hindu gods and goddesses as described in the Abhinaya Darpana. It indicates the form and character of the Hindu deity Kubera.",
  "technique": "Assume Alapadma Mudra with your left hand and Mushti Mudra with your right hand. Hold your hands about 6 inches in front of your body.",
  "application": "Used to indicate Kubera, the Hindu god of wealth.",
  "benefits": "",
  "note": "There are several combinations of mudras used to express the various traits and emblems of Kubera Deva. The gesture indicated here appears to be the most common.",
