  "hands": "joint",
  "description": "Kurma Mudra II is a less common variation of the eighteenth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "With each hand, fold the index, middle, and ring fingers into the palm. Extend the thumbs and little fingers away from each other. Join the two hands together as mirror images with the right on top of the left. The tips of the little fingers and thumbs touch, and the knuckles press together firmly.",
