  "description": "Makara Mudra I is a joint-hand dance gesture (samyukta hasta) noted in the Natya Shastra and in the Abhinaya Darpana. The patron deity associated with it is Mahendra.",
  "technique": "Palms facing downward, form Ardhachandra Mudra with each hand and cross the wrists. Thumbs move in circular motion.",
