  "hands": "joint",
  "description": "Matsya Mudra I is the seventeenth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "Place the right palm over the back your left hand, both palms facing downward. Keep all fingers collected, while extending the thumbs to the sides.",
