  "hands": "single",
  "description": "Mayura Mudra I is the fifth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. The name Vajrapataka Mudra is common to the Hindu tradition and it denotes the vajra (thunderbolt, weapon of Indra).",
  "technique": "Raise the hand, palm facing forward, fingers collected and extended upward. Maintain active fingers and a flat palm. Join the tips of the ring finger and the thumb.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Mayurasyam (“peacock beak”); Latayancha (“creeper vine”); Shakuna (“bird of omen”); Vamana (“vomiting”); Alakashya-apanayana (“stroking the hair” or “decorating the forehead”); Lalata-tilakam-shucha (“placing tilak on the forehead”); Nadi-udakasya-niksheypam (“sprinkling holy water over the head”); Shastra-vada (“discussing the shastras”); Prasidhaka (“renown”).",
