  "hands": "joint",
  "description": "Mudgara Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the twenty-third gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "Place the left palm under the right side of the chest. Form a fist with the right hand, resting the right elbow in the palm of the left hand. Keep the right forearm vertical.",
  "application": "In a comfortable seated position, relax the shoulders and breathe naturally. Imagine you are holding a weapon that defeats all your “inner demons” and reveals your true grace and talent. Hold for 5 to 30 minutes.",
  "benefits": "Increases courage, virtue, and loyalty, stimulates the immune system, activates the body’s self-healing power, and, according to the yoga tradition, facilitates the healing of major diseases such as cancer.",
