  "traditions": [
   "yoga"
  ],
  "hands": "joint",
  "description": "Mushtika Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the seventeenth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "With each hand, bring the pads of the fingers toward the heel of the hand. Join the hands together with the thumbs side by side.",
  "application": "In a comfortable seated position, hold the mudra lightly against your chest. Relax the shoulders, throat, and neck. Breathe naturally. Imagine there is a precious jewel of incalculable value inside your hands. This represents who you truly are, your unique gifts and talents. With sincerity in your heart, make an offering of the jewel internally as a commitment to live your life for the welfare of all beings. Do this repeatedly until tears of compassion flow from your eyes.",
  "benefits": "Weakens ego-grasping and self-defeating habits, awakens enlightened attitude and the heart of compassion, reduces anxiety and self-doubt, calms the spirit, clears the mind, benefits the heart and vascular system.",
  "note": "As you make the offering internally, you may also whisper the incantation, “I dedicate my thoughts, words, and actions to the welfare of all beings.”",
  "caution": "",
  "categories": [
   "Anxiety",
   "Spiritual Awakening"
  ],
  "chakras": [],
  "function": "Weakens ego-grasping and self-defeating habits",
