  "description": "Pasha Mudra is the fifteenth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "With the pads of the thumb, touch the nails of the middle, ring, and little fingers on each hand. Extend the index fingers and hook them together with one palm facing up, the other facing down.",
