  "hands": "joint",
  "description": "Pralamba Mudra is a joint-hand gesture (samyukta hasta) common to the yogic tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the sixteenth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "With the palms facing down, join the tips of the thumbs while keeping the other fingers collected.",
  "application": "In a comfortable seated position, hold the mudra in front of the abdomen. Soften the hands and relax the shoulders. Open your heart to hear the wishes and prayers of all beings—our shared longing to be free and happy. Respond with sincere blessings that you feel emanate from your hands like a huge garland of pearls, encircling the entire universe. Hold the mudra and visualization for 5 to 30 minutes.",
  "benefits": "Opens the heart, calms the spirit, awakens feelings of devotion and compassion, benefits the cardiovascular system by lowering blood pressure, reduces anxiety, weakens ego grasping.",
