  "hands": "single",
  "description": "Pushpa Mudra is a single-hand gesture (asamyukta hasta) noted in the Abhinaya Chandrika.",
  "technique": "Bend the little and ring fingers and tuck them into the center of your palm. Extend the thumb, middle, and index fingers upward, forming a triangle between the fingertips.",
  "application": "Used to denote a flower or flower offering in the dance tradition. It is also known in the Japanese Buddhist tradition as “the bodhisattva of flowers” and is used in specific rites and rituals to signify the offering of flowers.",
