  "description": "Pushpaputa Mudra is the sixth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra. The patron deity associated with it is Ksetrapala.",
  "technique": "With the palms facing upward, curve the hands and join the outer side of the little fingers, as if to create a basket-like shape in front of your heart center.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Nirajana-vidhau (“offering light”); Vari-phala-adigrahana (“receiving fruit or water”); Samdhyayam-arghya-dana (“twilight offering to the sun”); Mantra-pushpa (“offering flowers while chanting”). It is generally used to offer and receive flowers, fruit, corn, rice, or water.",
