  "hands": "joint",
  "description": "Rahu Mudra is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of the nine planets (Nava-Graha Hastas) as described in the Abhinaya Darpana. In Hindu mythology, Rahu is the severed head of an asura (demon) that swallows the sun or moon, thus causing eclipses. He is depicted in Indian art as a serpent with no body, riding a chariot drawn by eight black horses.",
  "technique": "Assume Sarpashirsha Mudra with your left hand and Suchi Mudra with your right hand. Place your hands in front of your chest. Evoke a cruel gaze.",
  "application": "To denote the ascending (north) lunar node, Rahu.",
  "benefits": "",
  "note": "",
  "caution": "",
  "categories": [
   "Dance & Expression"
  ],
