  "description": "Samputa Mudra II is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the second gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "Join the hands palm to palm with the thumbs resting side by side. Then, create a hollow space between the palms, large enough for the thumbs to enter the opening.",
  "application": "In a comfortable seated position, hold the mudra in front of the heart center. Relax the shoulders and chest, and breathe naturally. Bring your attention to the space between your hands. Hold this space delicately, as if carrying a baby bird. Hold for 5 to 30 minutes.",
