  "description": "Sarasvati Mudra is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of sixteen Deva Hastas, denoting Hindu gods and goddesses as described in the Abhinaya Darpana. It indicates the form and character of the Hindu deity Sarasvati.",
  "technique": "Assume Kapittha Mudra with your left hand, and Suchi Mudra with your right hand. Hold the left hand in front of the left shoulder with the index finger of your right hand pointing toward your left hand.",
  "application": "Used to indicate Sarasvati, the Hindu goddess of knowledge, music, art, science, and technology; consort of Brahma.",
  "benefits": "",
  "note": "There are several combinations of mudras used to express the various traits and emblems of Sarasvati Devi. The one indicated here appears to be the most common.",
