  "description": "Shakata Mudra II is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the twelfth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "With the palms facing down, lightly join the tips of the thumbs. Variation 1: Bend the index finger 90 degrees at the middle joint, and extend the remaining fingers (Image I). Variation 2: Extend the index fingers forward and curl the other fingers in toward the palms (Image II).",
  "application": "In a comfortable seated position, hold the mudra in front of the solar plexus. Relax the chest, shoulders, and belly. Breathe naturally and hold for 5 to 30 minutes.",
  "benefits": "Strengthens the immune system, facilitates breathing in the lower lobes of the lungs, improves concentration, benefits the large intestine.",
