  "technique": "Grasp the left thumb with the right hand. Bring the hands together, with the tip of the right thumb touching the tips of the left index, middle, and ring fingers.",
  "application": "Used by performing artists to signify the Shankha (“conch shell”), which often denotes Vishnu. It is one of the sacred emblems of the Hindu god of preservation (Vishnu). Vishnu holds the Shankha in his upper left hand, which represents his power to create and maintain the universe.",
