  "hands": "joint",
  "description": "Shankhavarta Mudra is a joint-hand gesture (samyukta hasta) common to the Buddhist Vajrayana tradition. It is a tantric mudra representing the conch shell, one of the Ashtamangala, “eight auspicious symbols,” the others being: a parasol, victory banner, golden fish, dharma (wheel), knot of wisdom, lotus flower, and treasure vase. These eight symbols represent the eight offerings made by the gods to Shakyamuni Buddha after he attained enlightenment.",
  "technique": "Raise the hands in front of the heart, palms facing each other. Join the tips of all the fingers. Bend the right index finger about 90 degrees at the middle joint.",
  "application": "In a comfortable seated position, hold the mudra in front of the heart. Relax the chest and shoulders, and breathe naturally. Become very still and quiet, listening to the silence. Hold for 5 to 45 minutes.",
  "benefits": "Quiets the mind, turns the attention inward, strengthens intuition, serves as a gateway to “hear” the wordless teachings of your own Original Nature.",
  "note": "",
  "caution": "",
  "categories": [
   "Intuition",
   "Spiritual Awakening"
  ],
  "chakras": [],
  "function": "Quiets the mind, turns the attention inward, strengthens intuition",
  "tidbit": "These eight symbols represent the eight offerings made by the gods to Shakyamuni Buddha after he attained enlightenment.",
