  "hands": "single",
  "description": "Shukatunda Mudra is the eighth hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra . According to mythology, it originated from Parvati who used it in a lovers’ quarrel with Sadashiva. The associated sage is Dhruvasa, race is Bramhana, color is red, and patron deity is Marici (or Sadashiva).",
  "technique": "Raise your hand to face outward with your fingers collected and extended upward. Bend the index and ring finger 90 degrees at the second joint.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Bana-prayuga (“shooting an arrow”); Kuntartha (“spear”); Alayasya-smritikarma (“remembering the past”); Marmukthyam (“mystic mood”); Ugrabhava (“ferocity”). Additional usages denote: Brahma’s weapon, nose, crookedness, change, turning around, proceeding, fighting, crossing, disrespect, lovers’ quarrel, opinion, abandonment, gambling dice, throwing a spear, ferocity, and secrecy.",
  "benefits": "",
  "note": "In the Hasta Lakshana Deepika, Shukatunda Mudra is noted as a different hand formation, identical to Tamrachuda Mudra of the Abhinaya Darpana.",
  "caution": "",
