  "application": "This mudra may be practiced in any position: walking, standing, seated, or lying down. It may be held with one hand, or both hands. For the purposes of deeper restoration and rejuvenation, it is best to practice lying down in shavasana (corpse pose). Hold for 5 to 30 minutes.",
