  "description": "Surya Mudra I is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of sixteen Deva Hastas, denoting Hindu gods and goddesses as described in the Abhinaya Darpana. It indicates the form and character of the Hindu deity Surya.",
  "technique": "Form Kapittha Mudra with your right hand and Alapadma Mudra with your left hand. Place both hands around chest level and stand in sama position (straight and elongated posture). Assume a pleasant gaze.",
  "application": "To denote the sun.",
  "benefits": "",
  "note": "In addition to this general mudra to indicate the sun, there are other hand formations mentioned in the Abhinaya Darpana that denote the rising sun, midday sun, and setting sun.",
