  "technique": "Cross the wrists with the palms resting on the upper chest. Keep the fingers extended and collected, palms flat (as in Pataka Mudra).",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Makara-artha (“crocodile”); Bhaya-vada (“timid speech”); Vivada (“dispute”); Kirtana (“praise”); Svastikaiya (“crossing”). The dynamic move of separating the hands apart represents movement of clouds, jungles, oceans, the earth, and vastness in general.",
