  "hands": "single",
  "description": "Tamrachuda Mudra is the twenty-seventh hand gesture of the twenty-eight single-hand mudras (asamyukta hastas) as described in the Abhinaya Darpana. According to mythology, this mudra came to exist when the three Vedas assumed physical form and stood before Brahama to make an exposition. The associated sage is Indra, race is Deva, color is mother-of-pearl, and patron deity is Brihaspati.",
  "technique": "Cover the nails of the middle, ring, and little finger under the tip of the thumb. Bend the index finger like a hook.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Kukkuta (“cock”); Bhaka (“crane”); Kaka (“crow”); Ushtra (“camel”); Vathsa (“calf”); Lekhanam (“writing instrument”).",
  "benefits": "",
  "note": "Tamrachuda Mudra is also noted in the Natya Shastra. However, its definition and application is identical to Trishula Mudra of the Abhinaya Darpana.",
  "caution": "",
  "categories": [
   "Dance & Expression"
  ],
  "chakras": [],
  "function": "Expresses cock, crane, crow, camel",
  "tidbit": "According to mythology, this mudra came to exist when the three Vedas assumed physical form and stood before Brahama to make an exposition.",
