  "description": "Ushas Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is used to open the doorway to new opportunities and courses of action.",
  "technique": "Clasp the hands with the left index finger on top. Bring the tips of the thumbs and index fingers toward each other, forming two open rings.",
