  "hands": "joint",
  "description": "Utsanga Mudra is the seventh hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana. It is also noted in the Natya Shastra. The patron deity associated with this mudra is Gautama.",
  "technique": "There are several variations of this gesture. Form Mrigashirsha, Arala, or Chatura Mudra with each hand. Cross the wrists with the palms facing you, and place the hands on the outer part of the upper chest.",
  "application": "Primarily used by performing artists to create context and express emotional states or specific actions. Viniyoga: Alingana (“embrace”); Lajayam (“modesty” or “shyness”); Angasa-adi-pradarshana (“showing armlets or the body”); Balanam-shikahana (“nursing a baby”). It is often used to express anything to do with touch, as well as effort or anger.",
  "benefits": "",
  "note": "The subtle specifics of this hand gesture, as well as the exact placement on the body, vary from one classical text to another.",
  "caution": "",
