  "hands": "joint",
  "description": "Uttarabodhi Mudra I is a joint-hand gesture (samyukta hasta) common to yoga tradition where it is used to connect with the source of one’s inspiration.",
  "technique": "Interlace the fingers with the tips of the thumbs and index fingers touching. Then, press the hands together, making the opening taller and more slender.",
  "application": "Hold the mudra in front of the chest, with the thumbs pointing down near the end of the sternum, and index fingers pointing up. You can practice while standing, seated, or lying down. Hold for 5 to 45 minutes.",
  "benefits": "Soothes the nervous system, tones the large intestine (improving absorption and elimination), benefits the lungs and heart, serves as conductor of inspiration and new energy.",
  "note": "This mudra may also be held in front of the pelvis with the tips of the index fingers pointed forward and slightly down.",
