  "hands": "joint",
  "description": "Vairagya Mudra is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the third gesture in the sub-set of eight mudras practiced after meditation or recitation of the Gayatri Mantra.",
  "technique": "Join the tips of the thumbs and index fingers of each hand. Place the hands lightly on the thighs, palms facing upward.",
  "application": "In a comfortable seated position, lengthen the spine, relax the shoulders and belly, and breathe naturally. Focus inward, feeling the hands like the two sides of a scale. Notice the feeling in your body and mind as you adjust your posture subtly to balance this scale. Hold for 5 to 45 minutes.",
  "benefits": "Improves memory, imparts a sense of balance and equanimity, increases mental and emotional flexibility, improves one’s ability to flow with changing circumstances, serves as an energy seal during meditation.",
