  "hands": "joint",
  "description": "Varaha Mudra I is the nineteenth hand gesture of the twenty-four joint-hand mudras (samyukta hastas) as described in the Abhinaya Darpana.",
  "technique": "Place the right palm over the back of the left hand. Bend the index, middle, and ring fingers at the base joint, maintaining extended and collected fingers. Stretch the little fingers directly forward to represent the tusks of the boar, and extend your thumbs sideways to represent the ears of the boar.",
  "application": "Used by performing artists to denote a boar. Varaha is known in the Hindu tradition as the third incarnation (“avatara”) of Vishnu. To indicate the movement of the boar, undulate the wrists in an up-and-down motion.",
  "benefits": "",
  "note": "",
  "caution": "",
