  "description": "Varaha Mudra III is a joint-hand gesture (samyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form, and is one of the traditional thirty-two Gayatri Mudras, specifically the twentieth gesture in the sub-set of twenty-four mudras practiced before meditation or recitation of the Gayatri Mantra.",
  "technique": "Hold the left hand with the palm facing you. Curl the middle, ring, and little fingers toward the palm with the index finger pointing to the right and the thumb extended upward. With the right hand, clasp the curled fingers of the left. Connect the right index finger to the left thumb. The left index finger rests on the outside of the right little finger.",
  "application": "In a comfortable seated position, hold the mudra in front of the chest. Lengthen the spine, relax the shoulders and belly, and breathe naturally. Hold for 5 to 45 minutes.",
