  "description": "Varuna Mudra II is single-hand gesture (asamyukta hasta) common to the yoga tradition. It is used in the Yoga Tattva Mudra Vijnana form to access the intelligence of the Water Element, and to increase the abundance of love, passion, and wholesome sexual expression.",
