  "application": "In a comfortable seated position, form the mudra with each hand and rest the hands on the thighs, palms facing up. With gratitude, connect with the spirit of water, feeling your body and mind become pure and fresh, like a cool mountain stream. Hold for 5 to 45 minutes.",
