  "hands": "single",
  "description": "Vayu Mudra II is a single-hand gesture (asamyukta hasta) common to the yoga tradition. It is found in the Yoga Tattva Mudra Vijnana form where it is used to treat complications related to the Air Element by controlling and balancing Vata Dosha (see Appendix A).",
  "technique": "Touch the tip of the index finger to the base of the thumb, with the thumb covering the index finger. Keep the other three fingers extended and relaxed.",
  "application": "Vayu Mudra may be used anytime in any position: walking, standing, sitting, or lying down. It is more effective to hold the mudra with each hand. For treatment of health conditions, it is ideal to practice 2 to 3 sessions per day of 10 to 45 minutes. Once the desired effects have been attained, discontinue regular practice of Vayu Mudra and continue a daily practice of Prana Mudra, Varuna Mudra and/or Prithivi Mudra.",
  "benefits": "Reduces gas, bloating, and belching, relieves headache, reduces symptoms of paralysis, treats diseases such as polio, gout, arthritis, sciatica, and muscular trembling (as is common in Parkinson’s disease).",
  "note": "Vayu Mudra yields improved results when practiced after Prana Mudra in a given session.",
  "caution": "",
  "categories": [
   "Arthritis",
   "Digestion",
   "Headache",
   "Tremors"
  ],
