  "description": "Vayu Mudra III is a joint-hand gesture (samyukta hasta) common to the Buddhist Vajrayana tradition. It is a tantric mudra held by priests during performance of the Garbhadhatu Mandala (“Womb Realm”) and the Vajradhatu Mandala (“Diamond Realm”) rites, where it symbolizes the auspicious wind that scatters delusion and clears obstacles.",
  "technique": "Touch the tip of the thumb to the base of the ring finger, and close the middle, ring, and little finger over the thumb. Hook the two index fingers at the first knuckle.",
  "application": "In a comfortable seated position, lengthen the spine, relax the shoulders and belly, and breathe naturally. Hold for 5 to 45 minutes.",
  "benefits": "Removes obstacles on the spiritual path, such as laziness, doubt, ignorance, egoism, excessive craving and aversion, and so on.",
