  "description": "Vishnu Mudra I is a joint-hand gesture (samyukta hasta) used by performing artists. It is found in the traditional set of sixteen Deva Hastas, denoting Hindu gods and goddesses as described in the Abhinaya Darpana. It indicates the form and character of the Hindu deity Vishnu.",
  "technique": "Assume Tripataka Mudra with each hand. Stand with your feet hip width apart. Hold the hands in front of the shoulders with the elbows at shoulder height, bending the wrists so your palms face away from you.",
  "application": "Used to indicate Vishnu, who is worshipped as the supreme god in the Vaishnava tradition of Hinduism.",
  "benefits": "",
