  "hands": "single",
  "description": "Vishnu Mudra II is a single-hand gesture (asamyukta hasta) common to the yoga tradition. It is used primarily during the practice of pranayama (breathing exercises) to control the left and right nostrils during techniques such as Nadi Shodhana Pranayama.",
  "technique": "Raise the right hand and fold the index and middle fingers into the palm. Extend the thumb, ring, and little fingers.",
  "application": "Use Vishnu Mudra to control the volume of air passing through the nostrils during breathing exercises.",
  "benefits": "Provides a comfortable and elegant way to employ the delicate pressure required to control the opening and closing of the nostrils during the practice of pranayama.",
  "note": "In the dance tradition, the same hand gesture is used to denote the amalaka tree. It is known as Samyama Nayaka Mudra in the Abhinaya Darpana.",
  "caution": "",
  "categories": [
   "General Practice"
  ],
