  "hands": "joint",
  "description": "Vishuddha Chakra Mudra is a joint-hand gesture (samyukta hasta) used in tantric Yoga and Japanese martial arts to open the Vishuddha Chakra (the throat energy center) and improve communication.",
  "technique": "Interlace the fingers of the hands with the tips pointing in toward the palms. Join the tips of the index fingers and thumbs, forming two interlocking rings.",
  "application": "In a comfortable seated position, hold the mudra in front of the throat. Place the tip of the tongue on the upper palate, and relax the shoulders and chest. Bring your attention to the spacious feeling inside the throat and neck. Settle into stillness and listen to the inner silence. Hold for 5 to 45 minutes.",
  "benefits": "Improves the health of the thyroid and parathyroid glands, benefits the voice, reduces tension in the neck, improves communication with self and others, increases sensitivity to the thoughts and feelings of others.",
  "note": "",
  "caution": "",
  "categories": [
   "Chakras",
   "Endocrine System",
   "Voice / Stuttering"
  ],
