  "technique": "Raise the hands in front of the belly, palms facing the midline, about 3 inches apart.",
  "application": "In a comfortable seated position, lengthen the spine and relax the shoulders, chest, and belly. Adjust your breathing to be slow, smooth, deep, and even. Feel the belly expand with the inhalation and contract with the exhalation. With the mudra held in front of your abdomen, feel a sense of thickness between your hands. Allow the hands to move ever so slightly apart as you inhale, and back together as you exhale. Practice this way for 5 to 20 minutes.",
